// Source 1 – HuggingFace ad copy → unified schema.
// Splits each ad into headline (first sentence), body (middle) and CTA (closing call to action).
const SOURCE = 'HuggingFace: jaykin01/advertisement-copy';
const SOURCE_URL = 'https://huggingface.co/datasets/jaykin01/advertisement-copy';
const DATASET_DATE = '2023-09-25'; // dataset last-updated date on HuggingFace (rows have no own date)
const collectedAt = new Date().toISOString();

const response = $input.first()?.json ?? {};
const rows = Array.isArray(response.rows) ? response.rows : [];

// Built-in check: failed or empty source → log it and keep the workflow going
if (response.error || rows.length === 0) {
  const reason = response.error ? (response.error.message || String(response.error)) : 'returned 0 records';
  console.log(`Source unavailable: ${SOURCE} (${reason})`);
  return [{ json: { _kind: 'source_status', source_name: SOURCE, status: 'unavailable', message: `Source unavailable: ${SOURCE} – ${reason}`, records_received: 0 } }];
}

const CTA_WORDS = /\b(shop|buy|order|get|grab|try|book|sign up|join|visit|call|discover|explore|learn|start|claim|save|upgrade|treat|elevate|experience|download|subscribe|reserve|enjoy|find|unlock|step|embrace|transform)\b/i;

const records = rows.map(({ row_idx, row }) => {
  const text = String(row.ad ?? '').trim();
  const tags = (text.match(/#\w+/g) || []).join(' ');
  const clean = text.replace(/#\w+/g, '').replace(/\s+/g, ' ').replace(/^"|"$/g, '').trim();
  const sentences = clean.split(/(?<=[.!?])\s+/).filter(Boolean);

  const headline = sentences[0] ?? '';
  let cta = '';
  let bodyParts = sentences.slice(1);
  const last = sentences[sentences.length - 1];
  if (sentences.length > 1 && CTA_WORDS.test(last)) {
    cta = last;
    bodyParts = sentences.slice(1, -1);
  }

  // Short ads (headline + CTA only): use the dataset's product description as the body, and say so
  let body = bodyParts.join(' ');
  const notes = ['date_from_dataset_release'];
  if (!body && row.description) { body = String(row.description).trim(); notes.push('body_from_product_description'); }

  return {
    json: {
      _kind: 'record',
      record_id: `AD-${String(row_idx + 1).padStart(4, '0')}`,
      source_name: SOURCE,
      source_type: 'ad_copy',
      title_or_headline: headline,
      body_text: body,
      cta,
      brand_or_product: String(row.product ?? '').trim(),
      channel: '',
      campaign_type: 'Product ad',
      audience: '',
      tags,
      published_date: DATASET_DATE,
      source_url: SOURCE_URL,
      collected_at: collectedAt,
      _notes: notes,
    },
  };
});

return [
  { json: { _kind: 'source_status', source_name: SOURCE, status: 'ok', message: `Loaded ${records.length} rows`, records_received: records.length } },
  ...records,
];

// Source 2 – HuggingFace campaign performance dataset → unified schema.
// Gives campaign context: type, channel, audience, date and results.
const SOURCE = 'HuggingFace: federicomoreno/marketing-campaign-performance-200k';
const SOURCE_URL = 'https://huggingface.co/datasets/federicomoreno/marketing-campaign-performance-200k';
const collectedAt = new Date().toISOString();

const response = $input.first()?.json ?? {};
const rows = Array.isArray(response.rows) ? response.rows : [];

// Built-in check: failed or empty source → log it and keep the workflow going
if (response.error || rows.length === 0) {
  const reason = response.error ? (response.error.message || String(response.error)) : 'returned 0 records';
  console.log(`Source unavailable: ${SOURCE} (${reason})`);
  return [{ json: { _kind: 'source_status', source_name: SOURCE, status: 'unavailable', message: `Source unavailable: ${SOURCE} – ${reason}`, records_received: 0 } }];
}

const records = rows.map(({ row }) => {
  const pct = (v) => (typeof v === 'number' ? `${Math.round(v * 100)}%` : 'n/a');
  const summary =
    `Targets ${row.Target_Audience} in ${row.Location} (${row.Language}) for ${row.Duration}. ` +
    `Conversion rate ${pct(row.Conversion_Rate)}, ROI ${row.ROI}, acquisition cost ${row.Acquisition_Cost}, ` +
    `${row.Clicks} clicks from ${row.Impressions} impressions, engagement score ${row.Engagement_Score}/10.`;

  return {
    json: {
      _kind: 'record',
      record_id: `CMP-${String(row.Campaign_ID).padStart(4, '0')}`,
      source_name: SOURCE,
      source_type: 'campaign_metadata',
      title_or_headline: `${row.Campaign_Type} campaign by ${row.Company} on ${row.Channel_Used}`,
      body_text: summary,
      cta: '',
      brand_or_product: String(row.Company ?? '').trim(),
      channel: String(row.Channel_Used ?? '').trim(),
      campaign_type: String(row.Campaign_Type ?? '').trim(),
      audience: `${row.Target_Audience ?? ''} · ${row.Customer_Segment ?? ''}`.trim(),
      tags: '',
      published_date: row.Date,
      source_url: SOURCE_URL,
      collected_at: collectedAt,
    },
  };
});

return [
  { json: { _kind: 'source_status', source_name: SOURCE, status: 'ok', message: `Loaded ${records.length} rows`, records_received: records.length } },
  ...records,
];

// Source 3 – four marketing RSS feeds → unified schema.
// Each feed is checked on its own, so one broken feed does not stop the others.
const FEEDS = [
  { node: 'RSS: MarTech', name: 'RSS: MarTech (martech.org)', prefix: 'MT' },
  { node: 'RSS: Marketing Dive', name: 'RSS: Marketing Dive', prefix: 'MD' },
  { node: 'RSS: HubSpot Marketing Blog', name: 'RSS: HubSpot Marketing Blog', prefix: 'HS' },
  { node: 'RSS: Social Media Examiner', name: 'RSS: Social Media Examiner', prefix: 'SME' },
];
const collectedAt = new Date().toISOString();
// Turn HTML (even escaped HTML like &lt;div&gt;) into plain readable text
const decode = (s) => s
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'")
  .replace(/&[lr]dquo;/g, '"').replace(/&[lr]squo;/g, "'").replace(/&mdash;/g, '—').replace(/&ndash;/g, '–').replace(/&hellip;/g, '…')
  .replace(/&nbsp;|&#160;/g, ' ').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n))).replace(/&amp;/g, '&');
const stripHtml = (s) => decode(decode(String(s ?? '')).replace(/<[^>]*>/g, ' ')).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

const output = [];
for (const feed of FEEDS) {
  let items = [];
  try { items = $(feed.node).all().map((i) => i.json); } catch (e) { items = []; }
  const failed = items.find((i) => i.error);
  const articles = items.filter((i) => !i.error && i.title);

  if (failed || articles.length === 0) {
    const reason = failed ? (failed.error.message || String(failed.error)) : 'returned 0 records';
    console.log(`Source unavailable: ${feed.name} (${reason})`);
    output.push({ json: { _kind: 'source_status', source_name: feed.name, status: 'unavailable', message: `Source unavailable: ${feed.name} – ${reason}`, records_received: 0 } });
    continue;
  }

  output.push({ json: { _kind: 'source_status', source_name: feed.name, status: 'ok', message: `Loaded ${articles.length} articles`, records_received: articles.length } });
  articles.forEach((a, i) => {
    // Remove the WordPress footer ("The post … appeared first on …") so only the real summary remains
    const summary = stripHtml(a.contentSnippet || a.content || a.summary).replace(/\s*The post .+ appeared first on .+$/, '').trim();
    output.push({
      json: {
        _kind: 'record',
        record_id: `${feed.prefix}-${String(i + 1).padStart(4, '0')}`,
        source_name: feed.name,
        source_type: 'industry_article',
        title_or_headline: stripHtml(a.title),
        body_text: summary.length > 500 ? summary.slice(0, 497).trimEnd() + '...' : summary,
        cta: '',
        brand_or_product: '',
        channel: 'Editorial / RSS',
        campaign_type: 'Industry brief',
        audience: '',
        tags: (Array.isArray(a.categories) ? a.categories : []).map((c) => (typeof c === 'string' ? c : c?._ ?? '')).filter(Boolean).slice(0, 5).join('; '),
        published_date: a.isoDate || a.pubDate || '',
        source_url: a.link || '',
        collected_at: collectedAt,
      },
    });
  });
}
return output;

// Quality step – runs on every record from every source.
// 1) trims text  2) standardises dates to YYYY-MM-DD  3) drops records missing title/date/source
// 4) removes duplicates  5) marks each record complete / incomplete with reasons
const all = $input.all().map((i) => i.json);
const records = all.filter((r) => r._kind === 'record');

// Which fields must be filled for a record to count as "complete", per source type
const REQUIRED = {
  ad_copy: ['title_or_headline', 'body_text', 'cta', 'brand_or_product'],
  campaign_metadata: ['title_or_headline', 'body_text', 'channel', 'campaign_type', 'audience'],
  industry_article: ['title_or_headline', 'body_text', 'source_url'],
};
const COLUMNS = ['record_id', 'source_name', 'source_type', 'title_or_headline', 'body_text', 'cta', 'brand_or_product', 'channel', 'campaign_type', 'audience', 'tags', 'published_date', 'source_url', 'collected_at', 'is_complete', 'quality_flags'];

const today = new Date();
const toIsoDate = (value) => {
  if (!value) return null;
  const s = String(value).trim();
  const d = /^\d{4}-\d{2}-\d{2}$/.test(s) ? new Date(s + 'T00:00:00Z') : new Date(s);
  if (isNaN(d.getTime())) return null;
  if (d.getUTCFullYear() < 2000 || d.getTime() > today.getTime() + 86400000) return null; // not a plausible date
  return d.toISOString().slice(0, 10);
};

const seen = new Set();
const clean = [];
const dropped = { missing_essentials: 0, invalid_date: 0, duplicates: 0 };

for (const r of records) {
  const rec = {};
  for (const col of COLUMNS) rec[col] = typeof r[col] === 'string' ? r[col].replace(/\s+/g, ' ').trim() : r[col] ?? '';

  // Essentials check – title, date and source must exist in EVERY record
  if (!rec.title_or_headline || !rec.source_name || !r.published_date) { dropped.missing_essentials++; continue; }

  // Date check – must parse to a real date
  const iso = toIsoDate(r.published_date);
  if (!iso) { dropped.invalid_date++; continue; }
  rec.published_date = iso;

  // Duplicate check – articles: same URL · ads: same product (the dataset repeats ads with shuffled sentences)
  // · campaigns: same campaign ID
  const norm = (v) => String(v).toLowerCase().replace(/[^a-z0-9]/g, '');
  const key = rec.source_type === 'industry_article' ? `url:${rec.source_url.toLowerCase()}`
    : rec.source_type === 'ad_copy' ? `ad:${norm(rec.brand_or_product)}`
    : `${rec.source_type}:${rec.record_id}`;
  if (seen.has(key)) { dropped.duplicates++; continue; }
  seen.add(key);

  // Completeness check – flag every missing field instead of hiding it
  const flags = (REQUIRED[rec.source_type] || []).filter((f) => !rec[f]).map((f) => `missing_${f}`);
  if (Array.isArray(r._notes)) flags.push(...r._notes); // informational notes, not missing data
  rec.is_complete = flags.every((f) => !f.startsWith('missing_'));
  rec.quality_flags = flags.join('; ');
  clean.push(rec);
}

// Keep a stable, readable order: by source type, then newest first
const order = { campaign_metadata: 1, ad_copy: 2, industry_article: 3 };
clean.sort((a, b) => order[a.source_type] - order[b.source_type] || b.published_date.localeCompare(a.published_date) || a.record_id.localeCompare(b.record_id));

// One bundle out: the clean records (split into CSV rows next) + the counts for the quality report
return [{ json: { records: clean, raw_records: records.length, removed: dropped } }];

// Quality report – the numbers for the documentation, calculated fresh on every run.
const { records: clean, raw_records, removed } = $input.first().json;
const statuses = $('Merge All Sources').all().map((i) => i.json).filter((r) => r._kind === 'source_status');

const pct = (a, b) => (b ? Math.round((a / b) * 1000) / 10 : 0);
const complete = clean.filter((r) => r.is_complete === true).length;

const perSource = statuses.map((s) => {
  const rows = clean.filter((r) => r.source_name === s.source_name);
  const done = rows.filter((r) => r.is_complete === true).length;
  const dates = rows.map((r) => r.published_date).sort();
  return {
    source_name: s.source_name,
    status: s.status,
    message: s.message,
    records_received: s.records_received,
    records_kept: rows.length,
    complete_records: done,
    completeness_pct: pct(done, rows.length),
    date_range: dates.length ? `${dates[0]} to ${dates[dates.length - 1]}` : '',
  };
});

const flagCounts = {};
for (const r of clean) for (const f of String(r.quality_flags || '').split('; ').filter(Boolean)) flagCounts[f] = (flagCounts[f] || 0) + 1;

const has = (r, f) => String(r[f] ?? '').trim() !== '';
return [{
  json: {
    report_generated_at: new Date().toISOString(),
    project: 'One Pipe – multi-source data pipeline',
    sources_attempted: statuses.length,
    sources_available: statuses.filter((s) => s.status === 'ok').length,
    unavailable_sources: statuses.filter((s) => s.status !== 'ok').map((s) => s.message),
    raw_records_collected: raw_records,
    records_removed: raw_records - clean.length,
    removed_breakdown: removed,
    clean_records: clean.length,
    complete_records: complete,
    quality_rate_pct: pct(complete, clean.length),
    essentials_check: {
      title_present_pct: pct(clean.filter((r) => has(r, 'title_or_headline')).length, clean.length),
      date_present_pct: pct(clean.filter((r) => has(r, 'published_date')).length, clean.length),
      source_present_pct: pct(clean.filter((r) => has(r, 'source_name') && has(r, 'source_url')).length, clean.length),
      dates_in_yyyy_mm_dd_pct: pct(clean.filter((r) => /^\d{4}-\d{2}-\d{2}$/.test(r.published_date)).length, clean.length),
    },
    per_source: perSource,
    quality_flag_counts: flagCounts,
  },
}];
